mapper.select:
SELECT supplier_id AS supplierId, COUNT(1) AS statementCount, IFNULL(SUM(amount), 0) AS totalAmount, IFNULL(SUM(paid_amount), 0) AS totalPaidAmount, IFNULL(SUM(remain_amount), 0) AS totalRemainAmount FROM erp_ap_statement WHERE deleted = 0 AND status != 40
AND supplier_id = #{supplierId}
GROUP BY supplier_id ORDER BY supplier_id DESC

SELECT supplier_id AS supplierId, IFNULL(SUM(CASE WHEN remain_amount > 0 AND DATEDIFF(#{reqVO.asOfDate}, due_date) BETWEEN 0 AND 30 THEN remain_amount ELSE 0 END), 0) AS amount0To30, IFNULL(SUM(CASE WHEN remain_amount > 0 AND DATEDIFF(#{reqVO.asOfDate}, due_date) BETWEEN 31 AND 60 THEN remain_amount ELSE 0 END), 0) AS amount31To60, IFNULL(SUM(CASE WHEN remain_amount > 0 AND DATEDIFF(#{reqVO.asOfDate}, due_date) BETWEEN 61 AND 90 THEN remain_amount ELSE 0 END), 0) AS amount61To90, IFNULL(SUM(CASE WHEN remain_amount > 0 AND DATEDIFF(#{reqVO.asOfDate}, due_date) > 90 THEN remain_amount ELSE 0 END), 0) AS amount91Plus, IFNULL(SUM(CASE WHEN remain_amount > 0 THEN remain_amount ELSE 0 END), 0) AS totalRemainAmount FROM erp_ap_statement WHERE deleted = 0 AND status != 40
AND supplier_id = #{reqVO.supplierId}
AND account_id = #{reqVO.accountId}
GROUP BY supplier_id HAVING totalRemainAmount > 0 ORDER BY supplier_id DESC

SELECT id AS statementId, statement_no AS statementNo, biz_type AS bizType, biz_id AS bizId, biz_no AS bizNo, source_order_id AS sourceOrderId, source_order_no AS sourceOrderNo, supplier_id AS supplierId, account_id AS accountId, amount, paid_amount AS paidAmount, remain_amount AS remainAmount, currency_code AS currencyCode, biz_date AS bizDate, due_date AS dueDate, invoice_status AS invoiceStatus, status, remark, create_time AS createTime FROM erp_ap_statement WHERE deleted = 0
AND supplier_id = #{reqVO.supplierId}
AND biz_type = #{reqVO.bizType}
AND statement_no LIKE CONCAT('%', #{reqVO.statementNo}, '%')
AND biz_no LIKE CONCAT('%', #{reqVO.bizNo}, '%')
AND status = #{reqVO.status}
AND biz_date >= #{reqVO.bizDate[0]}
AND biz_date <= #{reqVO.bizDate[1]}
ORDER BY id DESC
